// 단계 5 확장: 문제별 SQL과 풀이를 한곳에서 관리한다.
const problems = [];
function add(pack, n, title, topic, tables, columns, description, solution, explanation, skeleton, expectedRows) {
  const problem = { pack, id: `level5_${n}`, level: 5, title, topic, tables: tables.split(','), columns: columns.split(','), ordered: true,
    description: `${description} 결과 열은 ${columns} 순서다. 명시한 범위 외에는 전체 기간을 사용한다. 식별자 단위로 집계하며 이름이 같아도 합치지 않는다. 별도 언급 없는 동점은 모두 보존한다.`,
    solution, explanation, hints: [`핵심 개념: ${topic}. ${explanation.split('.')[0]}.`, explanation, `-- 주석 빈칸을 채우세요.\n${skeleton}`], starter: '-- 조건과 출력 열을 확인하세요.\nWITH ' };
  if (expectedRows) problem.expectedRows = expectedRows;
  problems.push(problem);
}
add('shop',15,'취소 이후 첫 결제 전환','순서가 있는 전환','customers,orders','customer_id,canceled_at,converted_at',
'취소 주문이 있는 고객만 첫 취소일과 그 날짜보다 엄격히 뒤인 최초 paid 주문일을 조회한다. 같은 날 결제는 전환이 아니다. 이후 결제가 없으면 converted_at은 NULL이다. 중복 주문은 최소 날짜에 영향을 주지 않는다. 고객 번호 오름차순이다.',
`WITH canceled AS (SELECT customer_id,MIN(ordered_at) AS canceled_at FROM orders WHERE status='canceled' GROUP BY customer_id) SELECT c.customer_id,c.canceled_at,MIN(o.ordered_at) AS converted_at FROM canceled c LEFT JOIN orders o ON o.customer_id=c.customer_id AND o.status='paid' AND o.ordered_at>c.canceled_at GROUP BY c.customer_id,c.canceled_at ORDER BY c.customer_id`,
'먼저 고객별 최초 취소일을 계산한다. 그보다 뒤인 결제만 외부 조인하고 최소 날짜를 구해 미전환도 남긴다.',
`WITH canceled AS (/* 고객별 최초 취소 */) SELECT c.customer_id,c.canceled_at,MIN(o.ordered_at) AS converted_at FROM canceled c LEFT JOIN orders o ON /* 취소보다 뒤인 결제 */ GROUP BY c.customer_id,c.canceled_at ORDER BY c.customer_id`,[[2,'2024-02-01',null]]);
add('shop',16,'첫 구매 장바구니의 재구매 상품','첫 주문 집합과 이후 교집합','orders,order_items','customer_id,first_products,repeated_products',
'paid 주문이 있는 고객별 첫 주문의 서로 다른 상품 수와 그 상품 중 이후 paid 주문에서 다시 산 상품 수를 구한다. 주문 순서는 주문일, 주문 번호 오름차순이며 같은 날도 번호가 크면 이후다. 상세 없는 첫 주문은 두 수 모두 0이다. 수량과 중복 상세는 상품 수를 늘리지 않는다. 고객 번호 오름차순이다.',
`WITH ranked AS (SELECT order_id,customer_id,ROW_NUMBER() OVER(PARTITION BY customer_id ORDER BY ordered_at,order_id) AS rn FROM orders WHERE status='paid'), first_items AS (SELECT DISTINCT r.customer_id,i.product_id FROM ranked r JOIN order_items i ON i.order_id=r.order_id WHERE r.rn=1), later_items AS (SELECT DISTINCT r.customer_id,i.product_id FROM ranked r JOIN order_items i ON i.order_id=r.order_id WHERE r.rn>1) SELECT r.customer_id,COUNT(f.product_id) AS first_products,COUNT(l.product_id) AS repeated_products FROM ranked r LEFT JOIN first_items f ON f.customer_id=r.customer_id LEFT JOIN later_items l ON l.customer_id=f.customer_id AND l.product_id=f.product_id WHERE r.rn=1 GROUP BY r.customer_id ORDER BY r.customer_id`,
'결제 주문에 고객별 순번을 붙인다. 첫 주문과 이후 주문의 상품 집합을 중복 제거한 뒤 교집합을 센다.',
`WITH ranked AS (/* 고객별 결제 순번 */), first_items AS (/* 첫 주문 상품 집합 */), later_items AS (/* 이후 상품 집합 */) SELECT /* 첫 집합과 교집합 개수 */ FROM ranked r LEFT JOIN first_items f ON /* 고객 */ LEFT JOIN later_items l ON /* 고객과 상품 */ WHERE r.rn=1 GROUP BY r.customer_id ORDER BY r.customer_id`,[[1,2,0],[2,1,0],[3,1,1],[4,1,0],[6,1,0]]);
add('shop',17,'달력 월별 신규·재방문 고객','신규와 기존 고객 분해','orders','month,new_customers,returning_customers',
'2024년 1~3월을 매월 한 행씩 조회한다. 그달 paid 주문 고객 중 전체 기간 첫 paid 주문의 월이 그달이면 신규, 이전 월이면 재방문이다. 같은 달 여러 주문은 고객당 한 번만 센다. 빈 달은 두 수 모두 0이며 월 YYYY-MM 오름차순이다.',
`WITH months AS (SELECT '2024-01' AS month UNION ALL SELECT '2024-02' UNION ALL SELECT '2024-03'), firsts AS (SELECT customer_id,DATE_FORMAT(MIN(ordered_at),'%Y-%m') AS first_month FROM orders WHERE status='paid' GROUP BY customer_id), active AS (SELECT DISTINCT customer_id,DATE_FORMAT(ordered_at,'%Y-%m') AS month FROM orders WHERE status='paid') SELECT m.month,COUNT(CASE WHEN f.first_month=m.month THEN a.customer_id END) AS new_customers,COUNT(CASE WHEN f.first_month<m.month THEN a.customer_id END) AS returning_customers FROM months m LEFT JOIN active a ON a.month=m.month LEFT JOIN firsts f ON f.customer_id=a.customer_id GROUP BY m.month ORDER BY m.month`,
'전체 기간에서 첫 결제 월을 구한 뒤 월별 활동 고객과 연결한다. 출력 달력에서 외부 조인하므로 빈 달도 보존한다.',
`WITH months AS (/* 1~3월 */), firsts AS (/* 최초 결제 월 */), active AS (/* 월별 고객 중복 제거 */) SELECT /* 신규와 재방문 조건부 개수 */ FROM months m LEFT JOIN active a ON /* 월 */ LEFT JOIN firsts f ON /* 고객 */ GROUP BY m.month ORDER BY m.month`,[['2024-01',2,0],['2024-02',2,1],['2024-03',0,1]]);
add('shop',18,'첫 결제 코호트의 두 달 연속 유지','다중 시점 리텐션','orders','cohort_month,cohort_size,retained_customers',
'첫 paid 주문 월별 고객 수와 그 다음 달 및 다다음 달 모두 paid 주문이 있는 고객 수를 구한다. 전체 기간의 첫 결제 월을 기준으로 하며 관측 종료 보정 없이 모든 코호트를 출력한다. 고객·월 중복 주문은 한 번만 센다. 유지 고객 없으면 0, 결제 없으면 빈 결과다. 코호트 월 오름차순이다.',
`WITH firsts AS (SELECT customer_id,CAST(DATE_FORMAT(MIN(ordered_at),'%Y-%m-01') AS DATE) AS first_month FROM orders WHERE status='paid' GROUP BY customer_id), flags AS (SELECT f.*,EXISTS(SELECT 1 FROM orders o WHERE o.customer_id=f.customer_id AND o.status='paid' AND o.ordered_at>=DATE_ADD(f.first_month,INTERVAL 1 MONTH) AND o.ordered_at<DATE_ADD(f.first_month,INTERVAL 2 MONTH)) AND EXISTS(SELECT 1 FROM orders o WHERE o.customer_id=f.customer_id AND o.status='paid' AND o.ordered_at>=DATE_ADD(f.first_month,INTERVAL 2 MONTH) AND o.ordered_at<DATE_ADD(f.first_month,INTERVAL 3 MONTH)) AS retained FROM firsts f) SELECT DATE_FORMAT(first_month,'%Y-%m') AS cohort_month,COUNT(*) AS cohort_size,SUM(retained) AS retained_customers FROM flags GROUP BY first_month ORDER BY cohort_month`,
'첫 결제 월을 월초 날짜로 고정한다. 서로 다른 두 달의 존재 여부를 AND로 결합한 고객 플래그를 합산한다.',
`WITH firsts AS (/* 고객별 최초 결제 월초 */), flags AS (SELECT f.*,/* 다음 달 EXISTS AND 다다음 달 EXISTS */ AS retained FROM firsts f) SELECT /* 코호트별 인원과 유지 합계 */ FROM flags GROUP BY first_month ORDER BY cohort_month`);
add('shop',19,'결제 후 장기 공백을 끝낸 주문','휴면 복귀 이벤트','orders','customer_id,order_id,previous_date,ordered_at,gap_days',
'고객별 paid 주문을 주문일·주문 번호 순으로 놓고 직전 paid 주문과 날짜 차이가 30일 이상인 복귀 주문을 모두 구한다. 첫 주문은 제외하며 같은 날 주문의 간격은 0이다. 상세 없는 주문도 인정한다. 고객 번호, 주문일, 주문 번호 오름차순이며 조건에 맞는 주문이 없으면 빈 결과다.',
`WITH gaps AS (SELECT customer_id,order_id,ordered_at,LAG(ordered_at) OVER(PARTITION BY customer_id ORDER BY ordered_at,order_id) AS previous_date FROM orders WHERE status='paid') SELECT customer_id,order_id,previous_date,ordered_at,DATEDIFF(ordered_at,previous_date) AS gap_days FROM gaps WHERE DATEDIFF(ordered_at,previous_date)>=30 ORDER BY customer_id,ordered_at,order_id`,
'취소를 제거한 주문열에서 직전 결제일을 구한다. 날짜 차이 필터는 윈도 함수 계산 다음 단계에서 적용한다.',
`WITH gaps AS (SELECT /* 주문 식별자와 LAG 날짜 */ FROM orders WHERE /* 결제 */) SELECT /* 날짜 차이 포함 */ FROM gaps WHERE /* 30일 이상 */ ORDER BY customer_id,ordered_at,order_id`);
add('shop',20,'연속 구매 구간 사이의 빈 날짜','연속 구간 사이 공백','orders','customer_id,gap_start,gap_end,idle_days',
'고객별 서로 다른 paid 주문일 중 인접 두 날짜 사이에 구매하지 않은 날이 하나 이상 있으면 그 공백의 시작일·종료일·일수를 출력한다. 첫 구매 이전과 마지막 구매 이후는 제외한다. 중복 주문일은 하루다. 고객 번호, 공백 시작일 오름차순이며 공백 없으면 빈 결과다.',
`WITH days AS (SELECT DISTINCT customer_id,ordered_at FROM orders WHERE status='paid'), neighbors AS (SELECT customer_id,ordered_at,LEAD(ordered_at) OVER(PARTITION BY customer_id ORDER BY ordered_at) AS next_date FROM days) SELECT customer_id,DATE_ADD(ordered_at,INTERVAL 1 DAY) AS gap_start,DATE_SUB(next_date,INTERVAL 1 DAY) AS gap_end,DATEDIFF(next_date,ordered_at)-1 AS idle_days FROM neighbors WHERE DATEDIFF(next_date,ordered_at)>1 ORDER BY customer_id,gap_start`,
'결제일 중복을 제거하고 다음 결제일을 찾는다. 양 끝의 결제일을 빼야 실제 비구매 일수가 된다.',
`WITH days AS (/* 결제 날짜 집합 */), neighbors AS (/* LEAD로 다음 날짜 */) SELECT /* 양 끝을 제외한 공백 */ FROM neighbors WHERE /* 날짜 차이가 1 초과 */ ORDER BY customer_id,gap_start`);
add('shop',21,'주문 상태가 유지되는 구간','범주 변화 세션','orders','customer_id,run_number,status,start_date,end_date,order_count',
'전체 주문을 고객별 주문일·주문 번호 오름차순으로 놓고 상태가 직전 주문과 달라질 때 새 구간을 시작한다. 날짜 공백만으로는 구간을 나누지 않는다. 고객별 구간 번호는 1부터 시작한다. 같은 날 주문도 개별 건수이며 고객 번호, 구간 번호 오름차순이다. 주문 없으면 빈 결과다.',
`WITH previous AS (SELECT o.*,LAG(status) OVER(PARTITION BY customer_id ORDER BY ordered_at,order_id) AS prev_status FROM orders o), numbered AS (SELECT *,SUM(CASE WHEN prev_status IS NULL OR prev_status<>status THEN 1 ELSE 0 END) OVER(PARTITION BY customer_id ORDER BY ordered_at,order_id ROWS UNBOUNDED PRECEDING) AS run_number FROM previous) SELECT customer_id,run_number,status,MIN(ordered_at) AS start_date,MAX(ordered_at) AS end_date,COUNT(*) AS order_count FROM numbered GROUP BY customer_id,run_number,status ORDER BY customer_id,run_number`,
'직전 상태와 현재 상태를 비교해 구간 시작 플래그를 만든다. 누적합으로 구간 번호를 부여한 뒤 구간별 집계한다.',
`WITH previous AS (/* LAG 상태 */), numbered AS (/* 상태 변화 플래그의 누적합 */) SELECT /* 구간별 시작·끝·건수 */ FROM numbered GROUP BY customer_id,run_number,status ORDER BY customer_id,run_number`);
add('shop',22,'달력 위의 누적 결제 고객','중복 없는 누적 고객','orders','sale_date,cumulative_customers',
'2024-01-01~2024-01-07 양 끝을 포함하여 매일 누적 paid 구매 고객 수를 출력한다. 해당 날짜까지 한 번이라도 결제한 고객을 세며 1월 이전 고객도 포함한다. 고객의 재구매는 증가시키지 않는다. 결제 없으면 매일 0이다. 날짜 오름차순이다.',
`WITH RECURSIVE calendar AS (SELECT CAST('2024-01-01' AS DATE) AS sale_date UNION ALL SELECT DATE_ADD(sale_date,INTERVAL 1 DAY) FROM calendar WHERE sale_date<'2024-01-07'), firsts AS (SELECT customer_id,MIN(ordered_at) AS first_date FROM orders WHERE status='paid' GROUP BY customer_id) SELECT c.sale_date,COUNT(f.customer_id) AS cumulative_customers FROM calendar c LEFT JOIN firsts f ON f.first_date<=c.sale_date GROUP BY c.sale_date ORDER BY c.sale_date`,
'고객마다 최초 결제일 한 행만 남긴다. 날짜 달력에 최초 결제일 이하 조건으로 연결하면 누적 고유 고객을 셀 수 있다.',
`WITH RECURSIVE calendar AS (/* 7일 생성 */), firsts AS (/* 고객별 첫 결제 */) SELECT c.sale_date,/* 누적 인원 */ FROM calendar c LEFT JOIN firsts f ON /* 첫 결제일 이하 */ GROUP BY c.sale_date ORDER BY c.sale_date`);
add('shop',23,'도시별 매출 집중도','허핀달 집중도','customers,orders,order_items','city,customer_count,concentration',
'도시별 모든 고객을 포함해 고객별 paid 매출을 구하고 고객 매출 비중 제곱의 합을 소수 넷째 자리로 출력한다. 상세 매출은 quantity*unit_price이며 중복 상세도 합산한다. 미구매·상세 없는 주문은 0이다. 도시 전체 매출이 0이면 concentration은 NULL이다. NULL 도시는 한 그룹이며 NULL 먼저, 도시 오름차순이다.',
`WITH totals AS (SELECT c.customer_id,c.city,COALESCE(SUM(i.quantity*i.unit_price),0) AS revenue FROM customers c LEFT JOIN orders o ON o.customer_id=c.customer_id AND o.status='paid' LEFT JOIN order_items i ON i.order_id=o.order_id GROUP BY c.customer_id,c.city), shares AS (SELECT *,SUM(revenue) OVER(PARTITION BY city) AS city_revenue FROM totals) SELECT city,COUNT(*) AS customer_count,ROUND(SUM(POWER(revenue/NULLIF(city_revenue,0),2)),4) AS concentration FROM shares GROUP BY city ORDER BY city`,
'먼저 고객 단위 매출로 상세 중복 영향을 정리한다. 도시 전체 매출로 나눈 고객 비중을 제곱해 합하고 0 분모는 NULL로 둔다.',
`WITH totals AS (/* 모든 고객 매출 */), shares AS (/* 도시별 총매출 윈도 합 */) SELECT city,COUNT(*) AS customer_count,/* 비중 제곱 합 */ AS concentration FROM shares GROUP BY city ORDER BY city`);
add('shop',24,'고객 매출의 지니 계수','쌍별 차이 기반 분포','customers,orders,order_items','customer_count,gini',
'모든 고객의 paid 매출을 사용해 지니 계수를 소수 넷째 자리로 한 행 출력한다. 지니는 모든 순서 있는 고객 쌍의 매출 절대 차이 합 / (2*고객 수*전체 매출)이다. 자기 자신과의 쌍도 포함한다. 중복 상세 매출은 합산하고 미구매 매출은 0이다. 고객이나 총매출이 없으면 gini는 NULL, 고객 수는 0일 수 있다. 단일 행이다.',
`WITH totals AS (SELECT c.customer_id,COALESCE(SUM(i.quantity*i.unit_price),0) AS revenue FROM customers c LEFT JOIN orders o ON o.customer_id=c.customer_id AND o.status='paid' LEFT JOIN order_items i ON i.order_id=o.order_id GROUP BY c.customer_id), stats AS (SELECT COUNT(*) AS n,SUM(revenue) AS revenue FROM totals), differences AS (SELECT SUM(ABS(a.revenue-b.revenue)) AS difference FROM totals a CROSS JOIN totals b) SELECT s.n AS customer_count,ROUND(d.difference/NULLIF(2*s.n*s.revenue,0),4) AS gini FROM stats s CROSS JOIN differences d ORDER BY customer_count`,
'고객 매출을 한 행씩 만든 뒤 순서 있는 모든 쌍의 절대 차이를 합한다. 공식의 분모가 0이면 NULL을 반환한다.',
`WITH totals AS (/* 고객별 매출 */), stats AS (/* 인원과 전체 매출 */), differences AS (/* 고객 쌍 절대 차이 합 */) SELECT /* 지니 공식 */ FROM stats s CROSS JOIN differences d ORDER BY customer_count`);
add('shop',25,'카테고리 매출 80퍼센트 핵심 상품','파레토 경계 포함','products,orders,order_items','category,product_id,revenue,cumulative_revenue',
'카테고리별 양수 paid 매출 상품을 매출 내림차순·상품 번호 오름차순으로 누적해 카테고리 매출의 80%에 처음 도달하는 상품까지 출력한다. 직전 누적이 80% 미만인 상품을 선택하므로 경계 상품을 포함한다. 중복 상세 합산, 무매출 카테고리 제외. 카테고리 오름차순, 매출 내림차순, 상품 번호 오름차순이다.',
`WITH sales AS (SELECT p.category,p.product_id,SUM(i.quantity*i.unit_price) AS revenue FROM products p JOIN order_items i ON i.product_id=p.product_id JOIN orders o ON o.order_id=i.order_id AND o.status='paid' GROUP BY p.category,p.product_id HAVING SUM(i.quantity*i.unit_price)>0), cumulative AS (SELECT *,SUM(revenue) OVER(PARTITION BY category) AS total,SUM(revenue) OVER(PARTITION BY category ORDER BY revenue DESC,product_id ROWS UNBOUNDED PRECEDING) AS cumulative_revenue FROM sales) SELECT category,product_id,revenue,cumulative_revenue FROM cumulative WHERE cumulative_revenue-revenue<total*0.8 ORDER BY category,revenue DESC,product_id`,
'상품 매출을 먼저 집계하고 카테고리 총매출과 정렬된 누적매출을 계산한다. 현재 상품 이전 누적값을 비교해야 임계점을 넘기는 상품도 남는다.',
`WITH sales AS (/* 양수 상품 매출 */), cumulative AS (/* 카테고리 합과 누적합 */) SELECT /* 핵심 상품 */ FROM cumulative WHERE /* 이전 누적 < 총매출 80% */ ORDER BY category,revenue DESC,product_id`);
add('shop',26,'구매 상품 집합의 진부분집합 고객','엄격한 집합 포함','customers,orders,order_items','customer_a,customer_b',
'고객 a의 paid 구매 상품 집합이 비어 있지 않고 b의 구매 상품 집합의 진부분집합인 방향 있는 쌍을 구한다. 모든 a 상품이 b에 있으며 b에만 있는 상품이 최소 하나 있어야 한다. 수량·중복 상세는 무시한다. 번호 크기 제한은 없다. customer_a,customer_b 오름차순이며 조건을 만족하지 않으면 빈 결과다.',
`WITH bought AS (SELECT DISTINCT o.customer_id,i.product_id FROM orders o JOIN order_items i ON i.order_id=o.order_id WHERE o.status='paid') SELECT a.customer_id AS customer_a,b.customer_id AS customer_b FROM customers a CROSS JOIN customers b WHERE EXISTS(SELECT 1 FROM bought x WHERE x.customer_id=a.customer_id) AND NOT EXISTS(SELECT 1 FROM bought x WHERE x.customer_id=a.customer_id AND NOT EXISTS(SELECT 1 FROM bought y WHERE y.customer_id=b.customer_id AND y.product_id=x.product_id)) AND EXISTS(SELECT 1 FROM bought y WHERE y.customer_id=b.customer_id AND NOT EXISTS(SELECT 1 FROM bought x WHERE x.customer_id=a.customer_id AND x.product_id=y.product_id)) ORDER BY customer_a,customer_b`,
'중복 제거한 구매 관계에서 a에서 b로의 차집합은 비우고 b에서 a로의 차집합은 남긴다. a의 비어 있지 않음도 별도로 검사한다.',
`WITH bought AS (/* 고객·상품 집합 */) SELECT /* 방향 있는 고객 쌍 */ FROM customers a CROSS JOIN customers b WHERE /* a 존재, a-b 공집합, b-a 비공집합 */ ORDER BY customer_a,customer_b`);
add('shop',27,'상품 구매 고객의 자카드 유사도','집합 교집합과 합집합','products,orders,order_items','product_a,product_b,jaccard',
'현재 모든 서로 다른 상품 쌍에 대해 paid 구매 고객 집합의 교집합 크기/합집합 크기를 소수 넷째 자리로 구한다. 작은 상품 번호를 a로 한다. 두 집합 모두 비면 NULL, 교집합만 비면 0이다. 같은 고객의 재구매와 중복 상세는 한 번이다. 상품 번호 a,b 오름차순이다.',
`WITH bought AS (SELECT DISTINCT i.product_id,o.customer_id FROM orders o JOIN order_items i ON i.order_id=o.order_id WHERE o.status='paid'), sizes AS (SELECT product_id,COUNT(*) AS n FROM bought GROUP BY product_id), intersections AS (SELECT a.product_id AS a,b.product_id AS b,COUNT(*) AS n FROM bought a JOIN bought b ON a.customer_id=b.customer_id AND a.product_id<b.product_id GROUP BY a.product_id,b.product_id) SELECT a.product_id AS product_a,b.product_id AS product_b,ROUND(COALESCE(x.n,0)/NULLIF(COALESCE(sa.n,0)+COALESCE(sb.n,0)-COALESCE(x.n,0),0),4) AS jaccard FROM products a JOIN products b ON a.product_id<b.product_id LEFT JOIN sizes sa ON sa.product_id=a.product_id LEFT JOIN sizes sb ON sb.product_id=b.product_id LEFT JOIN intersections x ON x.a=a.product_id AND x.b=b.product_id ORDER BY product_a,product_b`,
'상품별 고객 수와 상품 쌍의 공통 고객 수를 따로 센다. 합집합은 두 크기의 합에서 교집합을 빼서 구한다.',
`WITH bought AS (/* 상품·고객 중복 제거 */), sizes AS (/* 상품별 고객 수 */), intersections AS (/* 쌍별 공통 고객 */) SELECT /* 교집합/합집합 */ FROM products a JOIN products b ON /* 작은 번호 */ LEFT JOIN sizes sa ON /* a */ LEFT JOIN sizes sb ON /* b */ LEFT JOIN intersections x ON /* 쌍 */ ORDER BY product_a,product_b`);
add('shop',28,'등록된 모든 카테고리 경험자','그룹을 대상으로 하는 관계 나눗셈','customers,products,orders,order_items','customer_id',
'현재 products의 모든 서로 다른 category에서 상품을 하나 이상 paid 구매한 고객을 구한다. 각 카테고리의 전 상품을 살 필요는 없다. 전체 기간이며 중복 상품·주문은 영향 없다. 상품이 없어 카테고리 집합이 비면 모든 고객을 출력한다. 고객 번호 오름차순이다.',
`WITH categories AS (SELECT DISTINCT category FROM products), experienced AS (SELECT DISTINCT o.customer_id,p.category FROM orders o JOIN order_items i ON i.order_id=o.order_id JOIN products p ON p.product_id=i.product_id WHERE o.status='paid') SELECT c.customer_id FROM customers c WHERE NOT EXISTS(SELECT 1 FROM categories k WHERE NOT EXISTS(SELECT 1 FROM experienced e WHERE e.customer_id=c.customer_id AND e.category=k.category)) ORDER BY c.customer_id`,
'상품 대신 카테고리 집합을 나눗셈의 기준으로 삼는다. 경험하지 않은 카테고리가 없는 고객을 찾으면 빈 기준 집합도 처리된다.',
`WITH categories AS (/* 현재 카테고리 */), experienced AS (/* 고객별 경험 카테고리 */) SELECT c.customer_id FROM customers c WHERE NOT EXISTS(/* 경험하지 않은 카테고리 */) ORDER BY c.customer_id`);
add('shop',29,'일매출 하락 뒤 반등한 결제일','연속 관측값 패턴','orders,order_items','customer_id,ordered_at,daily_revenue',
'고객별 paid 결제일 매출을 집계해 바로 앞 두 결제일과 현재일의 매출이 하락한 뒤 반등한 경우 현재일을 출력한다. 즉 두 결제일 전 매출 > 직전 결제일 매출 < 현재 매출이다. 세 날짜가 달력상 연속일일 필요는 없다. 같은 날 모든 주문·중복 상세 합산, 상세 없는 날은 0. 앞 결제일이 두 개 미만이면 제외한다. 고객 번호, 날짜 오름차순이다.',
`WITH daily AS (SELECT o.customer_id,o.ordered_at,COALESCE(SUM(i.quantity*i.unit_price),0) AS daily_revenue FROM orders o LEFT JOIN order_items i ON i.order_id=o.order_id WHERE o.status='paid' GROUP BY o.customer_id,o.ordered_at), compared AS (SELECT *,LAG(daily_revenue) OVER(PARTITION BY customer_id ORDER BY ordered_at) AS prev1,LAG(daily_revenue,2) OVER(PARTITION BY customer_id ORDER BY ordered_at) AS prev2 FROM daily) SELECT customer_id,ordered_at,daily_revenue FROM compared WHERE prev2>prev1 AND prev1<daily_revenue ORDER BY customer_id,ordered_at`,
'일별 매출로 먼저 합친 뒤 한 칸과 두 칸 앞 매출을 비교한다. 같은 값은 하락이나 반등을 만족하지 않는다.',
`WITH daily AS (/* 고객별 일매출 */), compared AS (/* LAG 1,2 */) SELECT customer_id,ordered_at,daily_revenue FROM compared WHERE /* 하락 후 반등 */ ORDER BY customer_id,ordered_at`);
add('shop',30,'월별 고객 매출 점유율 변화','달력 패널과 전월 비교','customers,orders,order_items','customer_id,month,share_pct,change_pp',
'모든 고객에 대해 2024년 1~3월 매출 점유율과 전월 대비 퍼센트포인트 차이를 소수 둘째 자리로 출력한다. 분모는 해당 달 모든 고객의 paid 매출이다. 중복 상세는 합산한다. 고객 매출 없으면 0, 월 총매출 0이면 점유율 NULL이다. 1월 변화는 NULL이며 이전 또는 현재 점유율 NULL이면 변화도 NULL이다. 변화는 반올림 전 점유율로 계산한다. 고객 번호, 월 오름차순이다.',
`WITH months AS (SELECT '2024-01' AS month UNION ALL SELECT '2024-02' UNION ALL SELECT '2024-03'), sales AS (SELECT o.customer_id,DATE_FORMAT(o.ordered_at,'%Y-%m') AS month,SUM(i.quantity*i.unit_price) AS revenue FROM orders o JOIN order_items i ON i.order_id=o.order_id WHERE o.status='paid' GROUP BY o.customer_id,DATE_FORMAT(o.ordered_at,'%Y-%m')), panel AS (SELECT c.customer_id,m.month,COALESCE(s.revenue,0) AS revenue FROM customers c CROSS JOIN months m LEFT JOIN sales s ON s.customer_id=c.customer_id AND s.month=m.month), shares AS (SELECT customer_id,month,100.0*revenue/NULLIF(SUM(revenue) OVER(PARTITION BY month),0) AS share FROM panel) SELECT customer_id,month,ROUND(share,2) AS share_pct,ROUND(share-LAG(share) OVER(PARTITION BY customer_id ORDER BY month),2) AS change_pp FROM shares ORDER BY customer_id,month`,
'고객과 달력을 교차해 빠진 고객·월을 0으로 채운다. 월 전체 합계로 점유율을 만든 뒤 전월 차이를 계산한다.',
`WITH months AS (/* 1~3월 */), sales AS (/* 고객 월매출 */), panel AS (/* 고객×월과 매출 외부 조인 */), shares AS (/* 월내 비중 */) SELECT /* 비중과 LAG 차이 */ FROM shares ORDER BY customer_id,month`);
add('shop',31,'첫 두 주문의 카테고리 확장','장바구니 차집합','orders,order_items,products','customer_id,new_categories',
'paid 주문이 두 건 이상인 고객별 두 번째 주문에만 있는 카테고리 수를 출력한다. 순서는 주문일·주문 번호 오름차순이다. 상품·상세 중복은 카테고리를 늘리지 않는다. 첫 주문이 비면 두 번째의 모든 카테고리가 신규이며 두 번째 주문이 비면 0이다. 고객 번호 오름차순이다.',
`WITH ranked AS (SELECT order_id,customer_id,ROW_NUMBER() OVER(PARTITION BY customer_id ORDER BY ordered_at,order_id) AS rn FROM orders WHERE status='paid'), cats AS (SELECT DISTINCT r.customer_id,r.rn,p.category FROM ranked r JOIN order_items i ON i.order_id=r.order_id JOIN products p ON p.product_id=i.product_id WHERE r.rn<=2) SELECT r.customer_id,COUNT(c.category) AS new_categories FROM ranked r LEFT JOIN cats c ON c.customer_id=r.customer_id AND c.rn=2 AND NOT EXISTS(SELECT 1 FROM cats f WHERE f.customer_id=c.customer_id AND f.rn=1 AND f.category=c.category) WHERE r.rn=2 GROUP BY r.customer_id ORDER BY r.customer_id`,
'첫 두 주문의 카테고리를 각각 집합으로 만든다. 두 번째에 있으면서 첫 번째에 없는 카테고리만 외부 조인해 0건 고객도 보존한다.',
`WITH ranked AS (/* 결제 순번 */), cats AS (/* 첫 두 주문 카테고리 집합 */) SELECT /* 두 번째-첫 번째 개수 */ FROM ranked r LEFT JOIN cats c ON /* 두 번째이며 첫 번째에는 없음 */ WHERE r.rn=2 GROUP BY r.customer_id ORDER BY r.customer_id`);
add('shop',32,'월별 결제 고객 이탈과 유입','두 시점 집합 비교','orders','customer_id,movement',
'2024년 1월 또는 2월에 paid 주문한 고객을 한 행씩 출력한다. 양쪽 달 모두면 retained, 1월만이면 lost, 2월만이면 gained이다. 중복 주문은 한 번이며 두 달 모두 없으면 제외한다. 달 경계는 각각 월초 이상 다음 월초 미만이다. 고객 번호 오름차순이다.',
`WITH flags AS (SELECT customer_id,MAX(ordered_at<'2024-02-01') AS jan,MAX(ordered_at>='2024-02-01') AS feb FROM orders WHERE status='paid' AND ordered_at>='2024-01-01' AND ordered_at<'2024-03-01' GROUP BY customer_id) SELECT customer_id,CASE WHEN jan=1 AND feb=1 THEN 'retained' WHEN jan=1 THEN 'lost' ELSE 'gained' END AS movement FROM flags ORDER BY customer_id`,
'두 달의 합집합에서 고객별 월별 존재 플래그를 만든다. 두 플래그의 조합으로 유지·이탈·유입을 분류한다.',
`WITH flags AS (/* 고객별 1월·2월 존재 플래그 */) SELECT customer_id,CASE /* 플래그 조합 */ END AS movement FROM flags ORDER BY customer_id`);
add('shop',33,'최고 일매출 이후 최대 하락','누적 최고점 대비 낙폭','orders,order_items','customer_id,max_drawdown',
'paid 주문 고객별 일매출을 날짜순으로 놓고 해당 날짜까지의 최고 일매출에서 당일 매출을 뺀 값의 최댓값을 구한다. 주문 없는 날짜는 만들지 않는다. 중복 상세는 합산하고 상세 없는 결제일 매출은 0이다. 하락이 없으면 0, 결제 없는 고객 제외. 고객 번호 오름차순이다.',
`WITH daily AS (SELECT o.customer_id,o.ordered_at,COALESCE(SUM(i.quantity*i.unit_price),0) AS revenue FROM orders o LEFT JOIN order_items i ON i.order_id=o.order_id WHERE o.status='paid' GROUP BY o.customer_id,o.ordered_at), peaks AS (SELECT customer_id,revenue,MAX(revenue) OVER(PARTITION BY customer_id ORDER BY ordered_at ROWS UNBOUNDED PRECEDING) AS peak FROM daily) SELECT customer_id,MAX(peak-revenue) AS max_drawdown FROM peaks GROUP BY customer_id ORDER BY customer_id`,
'일별 매출의 누적 최댓값을 계산한다. 그 시점의 최고점 대비 차이를 구한 뒤 고객별 최대 차이를 선택한다.',
`WITH daily AS (/* 고객 일매출 */), peaks AS (/* 날짜순 누적 MAX */) SELECT customer_id,/* 최대 낙폭 */ AS max_drawdown FROM peaks GROUP BY customer_id ORDER BY customer_id`);
add('shop',34,'상품별 실제 구매 간격 평균','중복 날짜 제거 후 간격 평균','products,orders,order_items','product_id,average_gap_days',
'모든 상품에 대해 고객별 서로 다른 paid 구매일 사이 간격들을 모아 평균을 소수 둘째 자리로 구한다. 고객별 평균의 평균이 아니라 모든 관측 간격에 동일 가중치를 둔다. 같은 날 재구매와 중복 상세는 하루, 고객의 첫 날짜는 간격 없음으로 제외한다. 간격이 없으면 NULL이다. 상품 번호 오름차순이다.',
`WITH days AS (SELECT DISTINCT i.product_id,o.customer_id,o.ordered_at FROM orders o JOIN order_items i ON i.order_id=o.order_id WHERE o.status='paid'), gaps AS (SELECT product_id,DATEDIFF(ordered_at,LAG(ordered_at) OVER(PARTITION BY product_id,customer_id ORDER BY ordered_at)) AS gap_days FROM days), averages AS (SELECT product_id,ROUND(AVG(gap_days),2) AS average_gap_days FROM gaps GROUP BY product_id) SELECT p.product_id,a.average_gap_days FROM products p LEFT JOIN averages a ON a.product_id=p.product_id ORDER BY p.product_id`,
'상품·고객·날짜를 중복 제거한 뒤 같은 상품과 고객 내에서 날짜 차이를 구한다. 첫 관측의 NULL을 AVG가 제외하므로 간격만 평균된다.',
`WITH days AS (/* 상품 고객 날짜 집합 */), gaps AS (/* 상품·고객별 LAG 간격 */), averages AS (/* 상품별 간격 평균 */) SELECT p.product_id,a.average_gap_days FROM products p LEFT JOIN averages a ON /* 상품 */ ORDER BY p.product_id`);
add('shop',35,'월별 매출의 전월 대비 기여도','전체 증감 분해','products,orders,order_items','category,revenue_change,contribution_pct',
'현재 카테고리별 2024년 2월 paid 매출에서 1월 paid 매출을 뺀 변화량과 전체 매출 변화량 대비 기여 백분율을 소수 둘째 자리로 조회한다. 중복 상세는 합산하며 무매출 카테고리는 변화 0이다. 전체 변화가 0이면 기여율 NULL이며 음수 기여도 허용한다. 카테고리 오름차순이다.',
`WITH changes AS (SELECT p.category,SUM(CASE WHEN o.status='paid' AND o.ordered_at>='2024-02-01' AND o.ordered_at<'2024-03-01' THEN i.quantity*i.unit_price WHEN o.status='paid' AND o.ordered_at>='2024-01-01' AND o.ordered_at<'2024-02-01' THEN -i.quantity*i.unit_price ELSE 0 END) AS revenue_change FROM products p LEFT JOIN order_items i ON i.product_id=p.product_id LEFT JOIN orders o ON o.order_id=i.order_id GROUP BY p.category) SELECT category,revenue_change,ROUND(100.0*revenue_change/NULLIF(SUM(revenue_change) OVER(),0),2) AS contribution_pct FROM changes ORDER BY category`,
'두 달의 매출을 부호 있는 조건부 합계로 결합한다. 카테고리 변화의 전체 합을 분모로 써서 총변화를 분해한다.',
`WITH changes AS (/* 카테고리별 2월-1월 매출 */) SELECT category,revenue_change,/* 전체 변화 대비 비율 */ AS contribution_pct FROM changes ORDER BY category`);
add('shop',36,'주문 금액의 상위 이상치','사분위와 사분위 범위','orders,order_items','order_id,revenue,q1,q3',
'전체 paid 주문 금액을 오름차순·주문 번호 오름차순으로 놓고 최근접 순위 방식의 Q1=ceil(0.25*N)번째, Q3=ceil(0.75*N)번째 금액을 구한다. Q3+1.5*(Q3-Q1)보다 엄격히 큰 주문만 조회한다. 상세 없는 주문은 0, 중복 상세는 합산한다. 동액 경계는 제외하고 조건에 맞는 주문이나 결제가 없으면 빈 결과다. 주문 번호 오름차순이다.',
`WITH totals AS (SELECT o.order_id,COALESCE(SUM(i.quantity*i.unit_price),0) AS revenue FROM orders o LEFT JOIN order_items i ON i.order_id=o.order_id WHERE o.status='paid' GROUP BY o.order_id), ranked AS (SELECT *,ROW_NUMBER() OVER(ORDER BY revenue,order_id) AS rn,COUNT(*) OVER() AS n FROM totals), quartiles AS (SELECT MAX(CASE WHEN rn=CEIL(n*0.25) THEN revenue END) AS q1,MAX(CASE WHEN rn=CEIL(n*0.75) THEN revenue END) AS q3 FROM ranked) SELECT t.order_id,t.revenue,q.q1,q.q3 FROM totals t CROSS JOIN quartiles q WHERE t.revenue>q.q3+1.5*(q.q3-q.q1) ORDER BY t.order_id`,
'주문 금액을 먼저 만든 뒤 전체 개수와 순번으로 사분위 위치를 선택한다. 사분위 범위로 계산한 상한을 엄격히 넘는 주문을 찾는다.',
`WITH totals AS (/* 주문 금액 */), ranked AS (/* 순번과 N */), quartiles AS (/* ceil 위치의 Q1,Q3 */) SELECT /* 상한 초과 주문 */ FROM totals t CROSS JOIN quartiles q WHERE /* 이상치 조건 */ ORDER BY t.order_id`);
add('shop',37,'가입 후 구매 전환 퍼널','시간 순서를 지키는 퍼널','customers,products,orders,order_items','customer_count,buyer_count,multi_category_count',
'전체 고객 수, 가입일 이상에 paid 주문한 고객 수, 가입일 이상 paid 구매로 서로 다른 카테고리를 두 개 이상 경험한 고객 수를 한 행 출력한다. 가입 이전 주문은 제외한다. 상세 없는 결제도 구매자는 맞지만 카테고리 경험을 늘리지 않는다. 중복 상세·주문은 고객당 한 번 또는 카테고리당 한 번이다. 해당 고객 없으면 각 수는 0이다.',
`WITH flags AS (SELECT c.customer_id,COUNT(DISTINCT o.order_id) AS orders_count,COUNT(DISTINCT p.category) AS categories FROM customers c LEFT JOIN orders o ON o.customer_id=c.customer_id AND o.status='paid' AND o.ordered_at>=c.joined_at LEFT JOIN order_items i ON i.order_id=o.order_id LEFT JOIN products p ON p.product_id=i.product_id GROUP BY c.customer_id) SELECT COUNT(*) AS customer_count,COUNT(CASE WHEN orders_count>0 THEN 1 END) AS buyer_count,COUNT(CASE WHEN categories>=2 THEN 1 END) AS multi_category_count FROM flags ORDER BY customer_count`,
'가입 이후 결제만 조인한 고객별 퍼널 플래그를 만든다. 주문 존재와 카테고리 확장을 독립적으로 집계하고 고객 수로 환산한다.',
`WITH flags AS (/* 가입 이후 고객별 주문 수와 카테고리 수 */) SELECT /* 전체·구매·다중 카테고리 고객 수 */ FROM flags ORDER BY customer_count`);
add('academy',38,'미등록 응시의 회원별 비중','존재 조건과 분모 보존','members,attempts,enrollments','member_id,attempt_count,unregistered_count',
'모든 회원의 응시 수와 응시일 이하에 같은 강좌를 등록한 이력이 없는 응시 수를 구한다. 응시 후 등록은 인정하지 않는다. 미채점도 응시 한 건이며 재등록은 응시 수를 늘리지 않는다. 응시 없으면 두 수 모두 0이다. 회원 번호 오름차순이다.',
`WITH flagged AS (SELECT a.*,NOT EXISTS(SELECT 1 FROM enrollments e WHERE e.member_id=a.member_id AND e.course_id=a.course_id AND e.enrolled_at<=a.attempted_at) AS unregistered FROM attempts a) SELECT m.member_id,COUNT(f.attempt_id) AS attempt_count,COALESCE(SUM(f.unregistered),0) AS unregistered_count FROM members m LEFT JOIN flagged f ON f.member_id=m.member_id GROUP BY m.member_id ORDER BY m.member_id`,
'응시 시점 이전 등록 존재 여부를 응시별 플래그로 만든다. 회원 목록에 조인해 응시 없는 회원도 보존한다.',
`WITH flagged AS (SELECT a.*,/* 응시 시점 등록 NOT EXISTS */ AS unregistered FROM attempts a) SELECT /* 회원별 응시 수와 플래그 합 */ FROM members m LEFT JOIN flagged f ON /* 회원 */ GROUP BY m.member_id ORDER BY m.member_id`,[[1,4,0],[2,3,0],[3,2,1],[4,1,0],[5,0,0]]);
add('academy',39,'등록부터 최초 합격까지','기준 사건 이후 첫 성공','enrollments,attempts','member_id,course_id,enrolled_at,passed_at,days_to_pass',
'회원·강좌별 최초 등록일과 그 날짜 이상에 80점 이상 받은 최초 응시일, 날짜 차이를 조회한다. 재등록은 한 쌍으로 합친다. 미채점과 등록 전 합격은 무시하며 이후 합격이 없으면 날짜와 차이는 NULL이다. 같은 날 합격은 0일이다. 회원 번호, 강좌 번호 오름차순이다.',
`WITH firsts AS (SELECT member_id,course_id,MIN(enrolled_at) AS enrolled_at FROM enrollments GROUP BY member_id,course_id), passed AS (SELECT f.member_id,f.course_id,f.enrolled_at,MIN(a.attempted_at) AS passed_at FROM firsts f LEFT JOIN attempts a ON a.member_id=f.member_id AND a.course_id=f.course_id AND a.attempted_at>=f.enrolled_at AND a.score>=80 GROUP BY f.member_id,f.course_id,f.enrolled_at) SELECT member_id,course_id,enrolled_at,passed_at,DATEDIFF(passed_at,enrolled_at) AS days_to_pass FROM passed ORDER BY member_id,course_id`,
'회원·강좌별 최초 등록을 한 행으로 만든다. 유효한 합격 응시만 외부 조인하고 최초 합격 날짜에서 등록일을 뺀다.',
`WITH firsts AS (/* 쌍별 최초 등록 */), passed AS (/* 등록 이후 최초 80점 이상 */) SELECT /* 날짜와 날짜 차이 */ FROM passed ORDER BY member_id,course_id`,[[1,1,'2024-01-01','2024-01-10',9],[1,2,'2024-01-05','2024-01-20',15],[2,1,'2024-01-15','2024-01-16',1],[2,3,'2024-01-16',null,null],[3,1,'2024-02-01','2024-02-29',28],[4,3,'2024-01-01',null,null]]);
add('academy',40,'응시 성적의 최대 개선 폭','이전 최저점과 개선','attempts','member_id,course_id,max_improvement',
'채점된 응시가 있는 회원·강좌별 시간 순서상 이전 점수 대비 가능한 최대 개선 폭을 구한다. 순서는 응시일·응시 번호 오름차순이다. 이전 어느 점수와 비교해도 되며 감소만 있거나 채점 한 건이면 0이다. NULL 점수는 제외하고 0점은 포함한다. 회원 번호, 강좌 번호 오름차순이다.',
`WITH lows AS (SELECT member_id,course_id,score,MIN(score) OVER(PARTITION BY member_id,course_id ORDER BY attempted_at,attempt_id ROWS UNBOUNDED PRECEDING) AS lowest FROM attempts WHERE score IS NOT NULL) SELECT member_id,course_id,MAX(score-lowest) AS max_improvement FROM lows GROUP BY member_id,course_id ORDER BY member_id,course_id`,
'현재까지 최저 점수를 누적 MIN으로 구한다. 현재 자신을 포함하면 감소뿐인 경우에도 개선 폭의 최솟값이 0이 된다.',
`WITH lows AS (/* 회원·강좌별 누적 최저 채점 */) SELECT member_id,course_id,/* 최고 개선 */ AS max_improvement FROM lows GROUP BY member_id,course_id ORDER BY member_id,course_id`,[[1,1,30],[1,2,0],[2,1,0],[2,3,0],[3,1,0],[3,2,0],[4,3,0]]);
add('academy',41,'최초 학습 코호트의 일주일 재방문','구간 리텐션','activity','cohort_date,learners,returned_learners',
'회원별 첫 study 날짜를 코호트로 삼아 인원과 첫 학습일+1일부터 +7일까지 양 끝을 포함해 다시 study한 회원 수를 구한다. login은 무시하며 0분 study도 인정한다. 같은 날짜 여러 기록은 한 번, 첫날 추가 기록은 재방문이 아니다. 미활동 회원 제외, 재방문 없으면 0이다. 코호트 날짜 오름차순이다.',
`WITH firsts AS (SELECT member_id,MIN(activity_date) AS first_date FROM activity WHERE kind='study' GROUP BY member_id), flags AS (SELECT f.*,EXISTS(SELECT 1 FROM activity a WHERE a.member_id=f.member_id AND a.kind='study' AND a.activity_date>f.first_date AND a.activity_date<=DATE_ADD(f.first_date,INTERVAL 7 DAY)) AS returned FROM firsts f) SELECT first_date AS cohort_date,COUNT(*) AS learners,SUM(returned) AS returned_learners FROM flags GROUP BY first_date ORDER BY cohort_date`,
'가입일 대신 실제 첫 학습일로 코호트를 만든다. 최초 날짜를 제외한 일주일 구간의 존재 여부를 회원 단위로 합산한다.',
`WITH firsts AS (/* 회원별 첫 study 날짜 */), flags AS (/* 다음 7일 study 존재 */) SELECT /* 코호트 인원과 재방문 */ FROM flags GROUP BY first_date ORDER BY cohort_date`);
add('academy',42,'등록 코호트의 30일 완료율','관측 가능한 코호트','enrollments','cohort_month,enrollment_count,completed_count,completion_pct',
'2024-03-31 기준으로 등록일+30일이 기준일 이하인 등록 건만 등록 월별로 조회한다. 완료일이 NULL이 아니고 등록일부터 등록일+30일 사이 양 끝 포함이면 성공이다. 재등록도 각각 한 건이다. 완료 0건이면 비율 0이며 백분율 소수 둘째 자리다. 적격 등록 없는 월은 제외한다. 월 YYYY-MM 오름차순이다.',
`WITH eligible AS (SELECT *,CASE WHEN completed_at BETWEEN enrolled_at AND DATE_ADD(enrolled_at,INTERVAL 30 DAY) THEN 1 ELSE 0 END AS completed FROM enrollments WHERE DATE_ADD(enrolled_at,INTERVAL 30 DAY)<='2024-03-31') SELECT DATE_FORMAT(enrolled_at,'%Y-%m') AS cohort_month,COUNT(*) AS enrollment_count,SUM(completed) AS completed_count,ROUND(100.0*SUM(completed)/COUNT(*),2) AS completion_pct FROM eligible GROUP BY DATE_FORMAT(enrolled_at,'%Y-%m') ORDER BY cohort_month`,
'30일 관측 창이 끝난 등록만 먼저 남긴다. 완료 여부를 같은 창 안에서 평가해야 최근 등록이 불리하게 분모에 들어가지 않는다.',
`WITH eligible AS (/* 30일 관측 가능 등록과 창내 완료 플래그 */) SELECT /* 월별 완료율 */ FROM eligible GROUP BY DATE_FORMAT(enrolled_at,'%Y-%m') ORDER BY cohort_month`);
add('academy',43,'회원별 최초 완료 순서의 분야 전환','집계 사건열의 상태 변화','enrollments,courses','member_id,course_id,completed_at,previous_track,track',
'회원·강좌별 최초 완료 한 건을 남긴 뒤 완료일·강좌 번호 순으로 놓고 직전 완료 강좌와 분야가 다른 사건을 구한다. 미완료 등록은 무시하며 재완료는 사건을 늘리지 않는다. 첫 완료는 제외한다. 같은 날은 강좌 번호로 순서를 정한다. 회원 번호, 완료일, 강좌 번호 오름차순이다.',
`WITH firsts AS (SELECT member_id,course_id,MIN(completed_at) AS completed_at FROM enrollments WHERE completed_at IS NOT NULL GROUP BY member_id,course_id), sequenced AS (SELECT f.*,c.track,LAG(c.track) OVER(PARTITION BY f.member_id ORDER BY f.completed_at,f.course_id) AS previous_track FROM firsts f JOIN courses c ON c.course_id=f.course_id) SELECT member_id,course_id,completed_at,previous_track,track FROM sequenced WHERE previous_track<>track ORDER BY member_id,completed_at,course_id`,
'재등록의 완료를 회원·강좌 최초 사건으로 축약한다. 사건열에서 직전 분야를 구하고 달라진 사건만 남긴다.',
`WITH firsts AS (/* 쌍별 첫 완료 */), sequenced AS (/* 분야와 LAG 분야 */) SELECT /* 분야 전환 사건 */ FROM sequenced WHERE /* 직전 분야와 다름 */ ORDER BY member_id,completed_at,course_id`);
add('academy',44,'학습량이 증가한 연속 날짜 구간','날짜와 수치 조건의 구간화','activity','member_id,start_date,end_date,day_count',
'study 시간을 회원·날짜별 합산하고 직전 학습일과 정확히 하루 차이이며 시간이 엄격히 증가할 때만 같은 구간으로 잇는다. 그렇지 않으면 새 구간이다. 길이 2일 이상인 최대 구간을 모두 구한다. 0분도 학습일이고 중복 기록은 합산한다. login만 있는 날은 끊긴다. 회원 번호, 시작일 오름차순이다.',
`WITH daily AS (SELECT member_id,activity_date,SUM(duration) AS minutes FROM activity WHERE kind='study' GROUP BY member_id,activity_date), previous AS (SELECT *,LAG(activity_date) OVER(PARTITION BY member_id ORDER BY activity_date) AS prev_date,LAG(minutes) OVER(PARTITION BY member_id ORDER BY activity_date) AS prev_minutes FROM daily), numbered AS (SELECT *,SUM(CASE WHEN DATEDIFF(activity_date,prev_date)=1 AND minutes>prev_minutes THEN 0 ELSE 1 END) OVER(PARTITION BY member_id ORDER BY activity_date ROWS UNBOUNDED PRECEDING) AS grp FROM previous) SELECT member_id,MIN(activity_date) AS start_date,MAX(activity_date) AS end_date,COUNT(*) AS day_count FROM numbered GROUP BY member_id,grp HAVING COUNT(*)>=2 ORDER BY member_id,start_date`,
'직전 날짜와 시간 두 조건을 모두 확인해 구간 시작을 표시한다. 표시의 누적합으로 최대 구간을 구분하고 길이를 필터링한다.',
`WITH daily AS (/* study 일합계 */), previous AS (/* 직전 날짜·시간 */), numbered AS (/* 연속 증가가 아니면 새 구간 */) SELECT /* 구간별 길이 */ FROM numbered GROUP BY member_id,grp HAVING /* 2일 이상 */ ORDER BY member_id,start_date`);
add('academy',45,'연속 합격 응시 구간','NULL을 포함한 성공 연속성','attempts','member_id,course_id,start_attempt,end_attempt,pass_count',
'회원·강좌별 응시일·응시 번호 순서에서 80점 이상인 연속 합격 응시의 최대 구간을 모두 출력한다. 한 건짜리도 포함한다. 미채점 NULL과 80점 미만은 구간을 끊는다. start_attempt,end_attempt는 해당 구간 첫·마지막 응시 번호로 번호 최솟값·최댓값을 뜻하지 않는다. 회원 번호, 강좌 번호, 구간 시작 응시일, 시작 응시 번호 오름차순이다.',
`WITH numbered AS (SELECT *,SUM(CASE WHEN score>=80 THEN 0 ELSE 1 END) OVER(PARTITION BY member_id,course_id ORDER BY attempted_at,attempt_id ROWS UNBOUNDED PRECEDING) AS grp FROM attempts), passes AS (SELECT *,ROW_NUMBER() OVER(PARTITION BY member_id,course_id,grp ORDER BY attempted_at,attempt_id) AS rn_first,ROW_NUMBER() OVER(PARTITION BY member_id,course_id,grp ORDER BY attempted_at DESC,attempt_id DESC) AS rn_last FROM numbered WHERE score>=80) SELECT member_id,course_id,MAX(CASE WHEN rn_first=1 THEN attempt_id END) AS start_attempt,MAX(CASE WHEN rn_last=1 THEN attempt_id END) AS end_attempt,COUNT(*) AS pass_count FROM passes GROUP BY member_id,course_id,grp ORDER BY member_id,course_id,MIN(attempted_at),start_attempt`,
'실패와 미채점의 누적 개수로 합격 구간을 구분한다. 합격만 남긴 뒤 구간 내 양방향 순번으로 첫·마지막 응시 번호를 고른다.',
`WITH numbered AS (/* 실패·미채점 누적 개수 */), passes AS (/* 합격 필터 후 구간 양방향 순번 */) SELECT /* 첫·마지막 번호와 길이 */ FROM passes GROUP BY member_id,course_id,grp ORDER BY member_id,course_id,MIN(attempted_at),start_attempt`);
add('academy',46,'달력 기준 주간 학습일 비율','빈 날짜와 고유 활동일','members,activity','member_id,study_days,study_day_pct',
'모든 회원에 대해 2024-01-01~2024-01-07 양 끝 포함 7일 중 study가 존재한 날짜 수와 7일 대비 백분율을 소수 둘째 자리로 조회한다. 가입일로 기간을 줄이지 않는다. 0분 study 인정, 같은 날 중복은 하루, login 제외. 학습 없으면 두 값은 0이다. 회원 번호 오름차순이다.',
`WITH RECURSIVE calendar AS (SELECT CAST('2024-01-01' AS DATE) AS day UNION ALL SELECT DATE_ADD(day,INTERVAL 1 DAY) FROM calendar WHERE day<'2024-01-07'), days AS (SELECT DISTINCT member_id,activity_date FROM activity WHERE kind='study') SELECT m.member_id,COUNT(d.activity_date) AS study_days,ROUND(100.0*COUNT(d.activity_date)/7,2) AS study_day_pct FROM members m CROSS JOIN calendar c LEFT JOIN days d ON d.member_id=m.member_id AND d.activity_date=c.day GROUP BY m.member_id ORDER BY m.member_id`,
'7일 달력과 회원을 교차하고 학습 날짜 집합을 외부 조인한다. 기록 수 대신 일수를 세고 고정 7일로 나눈다.',
`WITH RECURSIVE calendar AS (/* 7일 */), days AS (/* study 날짜 집합 */) SELECT /* 날짜 수와 7일 대비 비율 */ FROM members m CROSS JOIN calendar c LEFT JOIN days d ON /* 회원과 날짜 */ GROUP BY m.member_id ORDER BY m.member_id`);
add('academy',47,'학습 시간 가중 중심 날짜','가중 평균 날짜','members,activity','member_id,weighted_day_offset',
'모든 회원에 대해 study 날짜와 가입일의 날짜 차이를 duration으로 가중 평균하여 소수 둘째 자리로 구한다. 가입 전 학습도 음수 차이로 포함한다. 중복 study는 모두 시간에 반영하고 login 제외. 총 study 시간이 0이면 NULL이며 기록 없는 회원도 NULL이다. 회원 번호 오름차순이다.',
`WITH weighted AS (SELECT m.member_id,SUM(DATEDIFF(a.activity_date,m.joined_at)*a.duration) AS numerator,SUM(a.duration) AS denominator FROM members m LEFT JOIN activity a ON a.member_id=m.member_id AND a.kind='study' GROUP BY m.member_id) SELECT member_id,ROUND(numerator/NULLIF(denominator,0),2) AS weighted_day_offset FROM weighted ORDER BY member_id`,
'가입일로부터 날짜 차이에 학습 시간을 곱한 합을 구한다. 이를 총시간으로 나누며 0분 기록은 무게를 갖지 않는다.',
`WITH weighted AS (/* 회원별 날짜차×시간 합과 시간 합 */) SELECT member_id,/* 가중 평균 */ AS weighted_day_offset FROM weighted ORDER BY member_id`);
add('academy',48,'강좌별 점수의 최빈값','동점 보존 분포','courses,attempts','course_id,score,frequency',
'각 강좌의 채점 응시 점수 빈도를 구하고 가장 자주 나온 점수를 모두 출력한다. 같은 회원의 재응시도 각각 한 건이다. NULL 점수는 제외하며 채점 없는 강좌는 출력하지 않는다. 최빈 빈도가 동점이면 모든 점수를 보존한다. 강좌 번호, 점수 오름차순이다.',
`WITH counts AS (SELECT course_id,score,COUNT(*) AS frequency FROM attempts WHERE score IS NOT NULL GROUP BY course_id,score), ranked AS (SELECT *,DENSE_RANK() OVER(PARTITION BY course_id ORDER BY frequency DESC) AS rnk FROM counts) SELECT course_id,score,frequency FROM ranked WHERE rnk=1 ORDER BY course_id,score`,
'점수별 빈도를 먼저 계산한 뒤 강좌 안에서 빈도 순위를 매긴다. DENSE_RANK의 1위를 모두 남겨 복수 최빈값을 보존한다.',
`WITH counts AS (/* 채점 점수별 빈도 */), ranked AS (/* 빈도 내림차순 순위 */) SELECT course_id,score,frequency FROM ranked WHERE /* 최빈 */ ORDER BY course_id,score`);
add('academy',49,'분야별 회원 최고점의 표준화','집계 후 표준점수','courses,attempts','track,member_id,best_score,z_score',
'분야·회원별 전체 채점 최고점을 구하고 같은 분야 회원 최고점 분포의 모집단 표준편차로 표준화한 z 점수를 소수 넷째 자리로 출력한다. 같은 회원의 여러 강좌·응시는 최고점 하나다. NULL 점수 제외, 채점 없는 회원·분야는 제외한다. 모집단 표준편차가 0이면 z_score는 NULL이다. 분야, 회원 번호 오름차순이다.',
`WITH best AS (SELECT c.track,a.member_id,MAX(a.score) AS best_score FROM attempts a JOIN courses c ON c.course_id=a.course_id WHERE a.score IS NOT NULL GROUP BY c.track,a.member_id), stats AS (SELECT track,AVG(best_score) AS mean_score,STDDEV_POP(best_score) AS sd FROM best GROUP BY track) SELECT b.track,b.member_id,b.best_score,ROUND((b.best_score-s.mean_score)/NULLIF(s.sd,0),4) AS z_score FROM best b JOIN stats s ON s.track=b.track ORDER BY b.track,b.member_id`,
'분야·회원별 최고점으로 관측 단위를 통일한다. 분야 평균과 모집단 표준편차를 별도로 구해 표준화한다.',
`WITH best AS (/* 분야 회원 최고점 */), stats AS (/* 분야 AVG와 STDDEV_POP */) SELECT /* 표준점수 */ FROM best b JOIN stats s ON /* 분야 */ ORDER BY b.track,b.member_id`);
add('academy',50,'회원 쌍의 완료 강좌 대칭차','집합 대칭차 크기','members,enrollments','member_a,member_b,different_courses',
'모든 서로 다른 회원 쌍에서 둘 중 정확히 한 명만 완료한 강좌 수를 구한다. 작은 번호가 member_a다. completed_at NULL은 완료가 아니며 재등록 완료는 강좌당 한 번이다. 양쪽 완료 집합이 같거나 둘 다 비면 0이다. 회원 a,b 오름차순이다.',
`WITH done AS (SELECT DISTINCT member_id,course_id FROM enrollments WHERE completed_at IS NOT NULL), sizes AS (SELECT member_id,COUNT(*) AS n FROM done GROUP BY member_id), common AS (SELECT a.member_id AS a,b.member_id AS b,COUNT(*) AS n FROM done a JOIN done b ON a.course_id=b.course_id AND a.member_id<b.member_id GROUP BY a.member_id,b.member_id) SELECT a.member_id AS member_a,b.member_id AS member_b,COALESCE(sa.n,0)+COALESCE(sb.n,0)-2*COALESCE(c.n,0) AS different_courses FROM members a JOIN members b ON a.member_id<b.member_id LEFT JOIN sizes sa ON sa.member_id=a.member_id LEFT JOIN sizes sb ON sb.member_id=b.member_id LEFT JOIN common c ON c.a=a.member_id AND c.b=b.member_id ORDER BY member_a,member_b`,
'완료 강좌 집합의 각 크기와 교집합 크기를 구한다. 두 크기의 합에서 교집합을 두 번 빼면 대칭차 크기가 된다.',
`WITH done AS (/* 완료 집합 */), sizes AS (/* 회원별 크기 */), common AS (/* 쌍별 교집합 */) SELECT /* 크기 합-교집합 두 배 */ FROM members a JOIN members b ON /* 작은 번호 */ LEFT JOIN sizes sa ON /* a */ LEFT JOIN sizes sb ON /* b */ LEFT JOIN common c ON /* 쌍 */ ORDER BY member_a,member_b`);
add('academy',51,'등록한 모든 강좌에서 합격한 회원','개인별 기준 집합 나눗셈','members,enrollments,attempts','member_id',
'적어도 한 강좌에 등록했으며 자신이 등록한 모든 강좌에서 전체 기간에 80점 이상을 한 번이라도 받은 회원을 조회한다. 등록 전 합격도 인정한다. 미채점은 합격이 아니고 재등록·재합격은 조건에 영향 없다. 미등록 강좌 응시는 무시한다. 등록 집합이 비면 제외하며 회원 번호 오름차순이다.',
`WITH registered AS (SELECT DISTINCT member_id,course_id FROM enrollments), passed AS (SELECT DISTINCT member_id,course_id FROM attempts WHERE score>=80) SELECT m.member_id FROM members m WHERE EXISTS(SELECT 1 FROM registered r WHERE r.member_id=m.member_id) AND NOT EXISTS(SELECT 1 FROM registered r WHERE r.member_id=m.member_id AND NOT EXISTS(SELECT 1 FROM passed p WHERE p.member_id=r.member_id AND p.course_id=r.course_id)) ORDER BY m.member_id`,
'전역 필수 강좌가 아니라 각 회원의 등록 집합을 기준으로 삼는다. 등록이 존재하고 미합격 등록 강좌가 없어야 한다.',
`WITH registered AS (/* 등록 집합 */), passed AS (/* 합격 집합 */) SELECT m.member_id FROM members m WHERE /* 등록 존재 AND 미합격 등록 부재 */ ORDER BY m.member_id`);
add('academy',52,'강좌의 모든 등록자가 완료했는가','중복 이력을 접은 전칭 조건','courses,enrollments','course_id,registered_members',
'적어도 한 명이 등록했고 등록한 모든 회원에게 그 강좌의 완료 이력이 있는 강좌를 조회한다. 한 회원의 미완료 재등록이 있어도 다른 등록에서 완료했으면 인정한다. 완료일 NULL만 있으면 미완료다. 등록 건수가 아닌 고유 회원 수를 출력한다. 강좌 번호 오름차순이다.',
`WITH flags AS (SELECT course_id,member_id,MAX(completed_at IS NOT NULL) AS done FROM enrollments GROUP BY course_id,member_id) SELECT course_id,COUNT(*) AS registered_members FROM flags GROUP BY course_id HAVING MIN(done)=1 ORDER BY course_id`,
'회원·강좌별 완료 여부를 MAX로 축약한다. 강좌 안에서 MIN이 1이어야 모든 등록 회원이 완료한 것이다.',
`WITH flags AS (/* 회원 강좌별 완료 플래그 */) SELECT course_id,COUNT(*) AS registered_members FROM flags GROUP BY course_id HAVING /* 모두 완료 */ ORDER BY course_id`);
add('academy',53,'등록 이력의 겹치는 수강 기간','구간 교집합','enrollments','enrollment_a,enrollment_b,overlap_start,overlap_end',
'2024-03-31까지 등록한 같은 회원의 서로 다른 등록 쌍 중 수강 기간이 겹치는 쌍을 구한다. 수강 기간은 등록일~완료일 양 끝 포함이며 NULL 완료일과 기준일 이후 완료일은 2024-03-31로 자른다. 같은 강좌 재등록 쌍도 포함한다. 작은 등록 번호가 a이며 경계 하루 겹침도 인정한다. 등록 번호 a,b 오름차순이다.',
`WITH periods AS (SELECT enrollment_id,member_id,enrolled_at,LEAST(COALESCE(completed_at,CAST('2024-03-31' AS DATE)),CAST('2024-03-31' AS DATE)) AS end_date FROM enrollments WHERE enrolled_at<='2024-03-31') SELECT a.enrollment_id AS enrollment_a,b.enrollment_id AS enrollment_b,GREATEST(a.enrolled_at,b.enrolled_at) AS overlap_start,LEAST(a.end_date,b.end_date) AS overlap_end FROM periods a JOIN periods b ON a.member_id=b.member_id AND a.enrollment_id<b.enrollment_id AND GREATEST(a.enrolled_at,b.enrolled_at)<=LEAST(a.end_date,b.end_date) ORDER BY enrollment_a,enrollment_b`,
'모든 기간의 끝을 기준일로 제한한다. 두 시작일 중 큰 값이 두 종료일 중 작은 값 이하이면 교집합이 존재한다.',
`WITH periods AS (/* 기준일로 절단한 등록 기간 */) SELECT /* 큰 시작일과 작은 종료일 */ FROM periods a JOIN periods b ON /* 같은 회원·작은 번호·교집합 존재 */ ORDER BY enrollment_a,enrollment_b`);
add('academy',54,'일별 진행 중 등록 수','날짜별 구간 스냅샷','enrollments','day,active_enrollments',
'2024-01-01~2024-01-07 매일 등록일이 해당 날짜 이하이고 완료일이 해당 날짜보다 뒤이거나 NULL인 등록 건수를 구한다. 완료 당일은 진행 중에서 제외한다. 재등록은 별도 건이며 같은 회원·강좌도 모두 센다. 등록 없으면 0이다. 날짜 오름차순이다.',
`WITH RECURSIVE calendar AS (SELECT CAST('2024-01-01' AS DATE) AS day UNION ALL SELECT DATE_ADD(day,INTERVAL 1 DAY) FROM calendar WHERE day<'2024-01-07') SELECT c.day,COUNT(e.enrollment_id) AS active_enrollments FROM calendar c LEFT JOIN enrollments e ON e.enrolled_at<=c.day AND (e.completed_at>c.day OR e.completed_at IS NULL) GROUP BY c.day ORDER BY c.day`,
'달력 날짜를 기준으로 시작일은 닫고 완료일은 연 반개구간 조건을 사용한다. COUNT에 등록 식별자를 넣어 빈 날짜를 0으로 센다.',
`WITH RECURSIVE calendar AS (/* 7일 */) SELECT c.day,COUNT(e.enrollment_id) AS active_enrollments FROM calendar c LEFT JOIN enrollments e ON /* 등록일 이하·완료일 초과 또는 NULL */ GROUP BY c.day ORDER BY c.day`);
add('academy',55,'회원별 학습 시간의 절반 도달일','자기 총량 기준 누적 경계','members,activity','member_id,halfway_date',
'모든 회원의 전체 study 총시간 중 절반 이상을 최초로 누적한 날짜를 구한다. 날짜별 중복 study 시간을 합친 뒤 날짜 순으로 누적한다. login 제외, 총시간 0 또는 study 없으면 NULL이다. 정확히 절반인 날도 도달로 인정한다. 회원 번호 오름차순이다.',
`WITH daily AS (SELECT member_id,activity_date,SUM(duration) AS minutes FROM activity WHERE kind='study' GROUP BY member_id,activity_date), running AS (SELECT *,SUM(minutes) OVER(PARTITION BY member_id) AS total,SUM(minutes) OVER(PARTITION BY member_id ORDER BY activity_date ROWS UNBOUNDED PRECEDING) AS accumulated FROM daily), reached AS (SELECT member_id,MIN(activity_date) AS halfway_date FROM running WHERE total>0 AND accumulated>=total/2 GROUP BY member_id) SELECT m.member_id,r.halfway_date FROM members m LEFT JOIN reached r ON r.member_id=m.member_id ORDER BY m.member_id`,
'고정 목표 대신 회원 자신의 전체 시간 절반을 기준으로 쓴다. 총량과 누적량을 함께 계산하고 조건을 처음 만족한 날짜를 선택한다.',
`WITH daily AS (/* 일별 시간 */), running AS (/* 전체 합과 누적 합 */), reached AS (/* 양수 총량의 절반 도달 최초일 */) SELECT m.member_id,r.halfway_date FROM members m LEFT JOIN reached r ON /* 회원 */ ORDER BY m.member_id`);
add('academy',56,'첫 합격 이후 재응시 악화','성공 이후 실패 사건','attempts','member_id,course_id,passed_attempt,failed_attempt',
'회원·강좌별 최초 80점 이상 합격 응시를 찾고 그 뒤 최초로 80점 미만을 받은 응시를 조회한다. 순서는 응시일·응시 번호 오름차순이므로 같은 날도 번호로 이후를 판단한다. NULL 점수는 합격도 실패도 아니다. 합격은 있으나 이후 실패가 없으면 failed_attempt NULL이다. 미합격 쌍 제외, 회원 번호·강좌 번호 오름차순이다.',
`WITH sequenced AS (SELECT *,ROW_NUMBER() OVER(PARTITION BY member_id,course_id ORDER BY attempted_at,attempt_id) AS seq FROM attempts), first_pass AS (SELECT member_id,course_id,MIN(seq) AS passed_seq FROM sequenced WHERE score>=80 GROUP BY member_id,course_id), first_fail AS (SELECT p.member_id,p.course_id,p.passed_seq,MIN(s.seq) AS failed_seq FROM first_pass p LEFT JOIN sequenced s ON s.member_id=p.member_id AND s.course_id=p.course_id AND s.seq>p.passed_seq AND s.score<80 GROUP BY p.member_id,p.course_id,p.passed_seq) SELECT f.member_id,f.course_id,p.attempt_id AS passed_attempt,s.attempt_id AS failed_attempt FROM first_fail f JOIN sequenced p ON p.member_id=f.member_id AND p.course_id=f.course_id AND p.seq=f.passed_seq LEFT JOIN sequenced s ON s.member_id=f.member_id AND s.course_id=f.course_id AND s.seq=f.failed_seq ORDER BY f.member_id,f.course_id`,
'먼저 모든 응시에 시간 순번을 부여한다. 최초 합격 순번보다 큰 실패 중 가장 이른 순번을 찾아 실제 응시 번호로 되돌린다.',
`WITH sequenced AS (/* 응시 순번 */), first_pass AS (/* 최초 합격 순번 */), first_fail AS (/* 그 뒤 최초 실패 순번 */) SELECT /* 실제 응시 번호 */ FROM first_fail f JOIN sequenced p ON /* 합격 순번 */ LEFT JOIN sequenced s ON /* 실패 순번 */ ORDER BY f.member_id,f.course_id`);
add('academy',57,'연속 날짜의 학습량 자기상관 재료','일별 패널의 곱 모멘트','members,activity','member_id,pair_count,mean_product',
'2024-01-01~2024-01-07 날짜별 study 시간에서 인접한 달력 날짜 6쌍의 시간 곱 평균을 모든 회원에 대해 소수 둘째 자리로 구한다. 미학습일은 0이며 같은 날 study는 합산하고 login 제외한다. pair_count는 각 회원 6이며 학습 없는 회원 mean_product는 0이다. 회원 번호 오름차순이다.',
`WITH RECURSIVE calendar AS (SELECT CAST('2024-01-01' AS DATE) AS day UNION ALL SELECT DATE_ADD(day,INTERVAL 1 DAY) FROM calendar WHERE day<'2024-01-07'), daily AS (SELECT member_id,activity_date,SUM(duration) AS minutes FROM activity WHERE kind='study' GROUP BY member_id,activity_date), panel AS (SELECT m.member_id,c.day,COALESCE(d.minutes,0) AS minutes FROM members m CROSS JOIN calendar c LEFT JOIN daily d ON d.member_id=m.member_id AND d.activity_date=c.day), pairs AS (SELECT *,LAG(minutes) OVER(PARTITION BY member_id ORDER BY day) AS previous_minutes FROM panel) SELECT member_id,COUNT(previous_minutes) AS pair_count,ROUND(AVG(minutes*previous_minutes),2) AS mean_product FROM pairs GROUP BY member_id ORDER BY member_id`,
'빈 날짜를 0으로 채운 회원·날짜 패널을 먼저 만든다. LAG로 인접 날짜 시간을 붙이면 첫날만 NULL이 되어 정확히 여섯 쌍이 평균된다.',
`WITH RECURSIVE calendar AS (/* 7일 */), daily AS (/* 일별 study 합 */), panel AS (/* 회원 날짜 패널 */), pairs AS (/* 직전 날짜 시간 */) SELECT /* 쌍 수와 곱 평균 */ FROM pairs GROUP BY member_id ORDER BY member_id`);
add('academy',58,'완료 후 다음 강좌 등록 전환','서로 다른 대상의 후속 사건','enrollments','member_id,course_id,completed_at,next_enrolled_at',
'회원·강좌별 최초 완료일을 구하고 그 날짜보다 엄격히 뒤에 등록한 다른 강좌의 최초 등록일을 조회한다. 같은 강좌 재등록과 완료 당일 등록은 제외한다. 중복 등록은 최소 날짜에 영향 없으며 이후 다른 강좌가 없으면 NULL이다. 미완료만 있는 쌍은 제외한다. 회원 번호, 강좌 번호 오름차순이다.',
`WITH completed AS (SELECT member_id,course_id,MIN(completed_at) AS completed_at FROM enrollments WHERE completed_at IS NOT NULL GROUP BY member_id,course_id) SELECT c.member_id,c.course_id,c.completed_at,MIN(e.enrolled_at) AS next_enrolled_at FROM completed c LEFT JOIN enrollments e ON e.member_id=c.member_id AND e.course_id<>c.course_id AND e.enrolled_at>c.completed_at GROUP BY c.member_id,c.course_id,c.completed_at ORDER BY c.member_id,c.course_id`,
'최초 완료 사건을 기준으로 회원은 같고 강좌는 다른 후속 등록을 찾는다. 완료일보다 뒤라는 시간 조건을 외부 조인에 넣어 미전환을 보존한다.',
`WITH completed AS (/* 쌍별 최초 완료 */) SELECT /* 이후 다른 강좌의 최초 등록일 */ FROM completed c LEFT JOIN enrollments e ON /* 같은 회원·다른 강좌·완료 후 */ GROUP BY c.member_id,c.course_id,c.completed_at ORDER BY c.member_id,c.course_id`);
add('academy',59,'필수 강좌 완료까지 남은 개수의 달력','시점별 관계 나눗셈 진행도','members,courses,enrollments','member_id,checkpoint,remaining_courses',
'모든 회원에 대해 2024-01-31,2024-02-29,2024-03-31 각각 해당 날짜까지 완료하지 않은 현재 필수 강좌 수를 구한다. 완료일은 기준일 이하를 인정하고 NULL은 미완료다. 재등록은 완료 이력 한 번이면 인정한다. 필수 강좌가 없거나 모두 완료면 0이며 미등록 강좌도 남은 수에 포함한다. 회원 번호, 기준일 오름차순이다.',
`WITH checkpoints AS (SELECT CAST('2024-01-31' AS DATE) AS checkpoint UNION ALL SELECT CAST('2024-02-29' AS DATE) UNION ALL SELECT CAST('2024-03-31' AS DATE)), done AS (SELECT member_id,course_id,MIN(completed_at) AS completed_at FROM enrollments WHERE completed_at IS NOT NULL GROUP BY member_id,course_id) SELECT m.member_id,t.checkpoint,COUNT(CASE WHEN d.completed_at IS NULL OR d.completed_at>t.checkpoint THEN c.course_id END) AS remaining_courses FROM members m CROSS JOIN checkpoints t LEFT JOIN courses c ON c.required=1 LEFT JOIN done d ON d.member_id=m.member_id AND d.course_id=c.course_id GROUP BY m.member_id,t.checkpoint ORDER BY m.member_id,t.checkpoint`,
'각 회원과 세 기준일을 교차하고 현재 필수 강좌를 붙인다. 강좌별 최초 완료가 기준일 뒤이거나 없으면 남은 강좌로 센다.',
`WITH checkpoints AS (/* 세 월말 */), done AS (/* 쌍별 최초 완료 */) SELECT /* 미완료 필수 강좌 수 */ FROM members m CROSS JOIN checkpoints t LEFT JOIN courses c ON /* 필수 */ LEFT JOIN done d ON /* 회원 강좌 */ GROUP BY m.member_id,t.checkpoint ORDER BY m.member_id,t.checkpoint`);
add('academy',60,'분야별 학습 성과의 파레토 회원','다중 지표 지배 관계','courses,attempts,enrollments','track,member_id,passed_courses,completed_courses',
'분야별로 그 분야에 등록 또는 응시한 회원을 대상으로 합격 강좌 수와 완료 강좌 수를 구한다. 합격은 전체 기간 80점 이상 한 번, 완료는 NULL 아닌 완료일 한 번이며 각 강좌는 한 번만 센다. 두 지표 모두 자신 이상이고 최소 하나가 더 큰 다른 회원이 같은 분야에 없으면 출력한다. 등록 없이 합격도 인정하며 없는 지표는 0이다. 두 지표가 모두 동점이면 모두 보존한다. 분야, 회원 번호 오름차순이다.',
`WITH participants AS (SELECT c.track,e.member_id FROM enrollments e JOIN courses c ON c.course_id=e.course_id UNION SELECT c.track,a.member_id FROM attempts a JOIN courses c ON c.course_id=a.course_id), passed AS (SELECT c.track,a.member_id,COUNT(DISTINCT a.course_id) AS n FROM attempts a JOIN courses c ON c.course_id=a.course_id WHERE a.score>=80 GROUP BY c.track,a.member_id), completed AS (SELECT c.track,e.member_id,COUNT(DISTINCT e.course_id) AS n FROM enrollments e JOIN courses c ON c.course_id=e.course_id WHERE e.completed_at IS NOT NULL GROUP BY c.track,e.member_id), metrics AS (SELECT p.track,p.member_id,COALESCE(a.n,0) AS passed_courses,COALESCE(e.n,0) AS completed_courses FROM participants p LEFT JOIN passed a ON a.track=p.track AND a.member_id=p.member_id LEFT JOIN completed e ON e.track=p.track AND e.member_id=p.member_id) SELECT m.track,m.member_id,m.passed_courses,m.completed_courses FROM metrics m WHERE NOT EXISTS(SELECT 1 FROM metrics x WHERE x.track=m.track AND x.passed_courses>=m.passed_courses AND x.completed_courses>=m.completed_courses AND (x.passed_courses>m.passed_courses OR x.completed_courses>m.completed_courses)) ORDER BY m.track,m.member_id`,
'등록과 응시의 합집합으로 분야별 참여자를 만든다. 두 지표를 별도 집계한 뒤 자신을 엄격히 지배하는 다른 회원이 없는 행을 남긴다.',
`WITH participants AS (/* 등록·응시 참여자 합집합 */), passed AS (/* 합격 강좌 수 */), completed AS (/* 완료 강좌 수 */), metrics AS (/* 참여자에 지표 0 보완 */) SELECT /* 비지배 회원 */ FROM metrics m WHERE NOT EXISTS(/* 두 지표 모두 이상이며 하나는 초과 */) ORDER BY m.track,m.member_id`);

// 실행 가능한 오답: 각각 날짜 경계, 중복, 시간 순서, NULL 처리의 함정을 검증한다.
problems.find(p => p.id === 'level5_15').wrongSql = problems.find(p => p.id === 'level5_15').solution.replace('o.ordered_at>c.canceled_at', 'o.ordered_at<c.canceled_at');
problems.find(p => p.id === 'level5_16').wrongSql = problems.find(p => p.id === 'level5_16').solution.replace('COUNT(l.product_id)', 'COUNT(f.product_id)');
problems.find(p => p.id === 'level5_38').wrongSql = problems.find(p => p.id === 'level5_38').solution.replace(' AND e.course_id=a.course_id', '');
problems.find(p => p.id === 'level5_40').wrongSql = problems.find(p => p.id === 'level5_40').solution.replace('MAX(score-lowest)', 'MIN(score-lowest)');
module.exports = problems;

// node content/extra-advanced.cjs: 형식과 중복을 재현 가능하게 검사한다.
if (require.main === module) {
  const assert = require('node:assert/strict');
  assert.equal(problems.length, 46);
  assert.equal(new Set(problems.map(p => p.id)).size, 46);
  assert.equal(new Set(problems.map(p => p.title)).size, 46);
  assert.equal(new Set(problems.map(p => p.solution)).size, 46);
  assert.ok(problems.filter(p => p.expectedRows).length >= 6);
  assert.ok(problems.filter(p => p.wrongSql).length >= 4);
  for (const p of problems) {
    assert.equal(p.hints.length, 3);
    assert.ok(p.hints[2].includes('/*'));
    assert.ok(p.solution.includes('ORDER BY'));
    assert.ok(p.expectedRows === undefined || p.expectedRows.every(row => row.length === p.columns.length));
  }
  console.log('단계 5 신규 46문제: 형식·힌트·식별자·중복·공개 기대값 검증 통과');
}
